def parse_and_sort_monsters(text_data):
    """
    Parses the provided text data to extract monster names, categorized by step and type,
    then sorts them alphabetically.

    Args:
        text_data (str): The input text containing monster information.

    Returns:
        dict: A dictionary where keys are step numbers and values are dictionaries
              containing lists of sorted monster names for 'Monstres', 'Boss de donjon',
              and 'Archimonstres'.
    """
    parsed_data = {}
    current_step = None
    current_category = None

    # Split the text into sections based on "Étape X :"
    steps = re.split(r'(Étape \d+ : )', text_data)
    # The split creates empty strings and the delimiters themselves, so we process them.
    # We iterate by pairs: (delimiter, content)
    for i in range(1, len(steps), 2):
        step_header = steps[i].strip()
        step_content = steps[i+1].strip()

        # Extract step number
        step_match = re.search(r'Étape (\d+)', step_header)
        if step_match:
            current_step = int(step_match.group(1))
            parsed_data[current_step] = {
                "Monstres": set(),
                "Boss de donjon": set(),
                "Archimonstres": set()
            }

            # Split content by categories
            categories = re.split(r'(Monstres|Boss de donjon|Archimonstres|Récompenses : \d+ XP)', step_content)
            
            # Iterate through category headers and their content
            for j in range(1, len(categories), 2):
                category_header = categories[j].strip()
                category_content = categories[j+1].strip()

                if category_header in ["Monstres", "Boss de donjon", "Archimonstres"]:
                    current_category = category_header
                    # Use regex to find monster names.
                    # For regular monsters/bosses: capture text before first '('.
                    # For archimonstres: capture text before first '(' and text inside first '()'.
                    if current_category == "Archimonstres":
                        # Archimonstres have a specific format: Name (Base Monster)
                        monster_matches = re.findall(r'([A-Za-zÀ-ÿ\'\s-]+)\s*\((.*?)\)', category_content)
                        for archimonster_name, base_monster_name in monster_matches:
                            # Store both names for Archimonstres, or just the main one.
                            # For simplicity, let's store "Archimonster (Base Monster)" as one entry
                            parsed_data[current_step][current_category].add(f"{archimonster_name.strip()} ({base_monster_name.strip()})")
                    else:
                        # For regular monsters and bosses, extract names before the first parenthesis
                        # This regex captures words followed by optional spaces and hyphens, up to an opening parenthesis.
                        monster_matches = re.findall(r'([A-Za-zÀ-ÿ\s\'-]+?)\s*\(', category_content)
                        for monster_name in monster_matches:
                            parsed_data[current_step][current_category].add(monster_name.strip())

    # Sort the monster names within each category and step
    sorted_parsed_data = {}
    for step, categories_data in parsed_data.items():
        sorted_parsed_data[step] = {}
        for category, monsters_set in categories_data.items():
            sorted_parsed_data[step][category] = sorted(list(monsters_set))
    
    return sorted_parsed_data

